# Object storage locator: parse URIs into (namespace, bucket, key), resolve aliases.
import re
def parse(uri):
    m = re.match(r"(\w+)://([^/]+)/?(.*)", uri)
    if not m: return None
    scheme, bucket, key = m.groups()
    ns = {"s3": "aws", "gs": "gcp", "az": "azure"}.get(scheme, scheme)
    return {"namespace": ns, "bucket": bucket, "key": key}
aliases = {}
for uri in ['s3://photos/2024/a.jpg', 'gs://data/f.csv']:
    p = parse(uri)
    real = aliases.get(p["bucket"], p["bucket"]) if p else None
    print(f"{uri}\n  -> ns={p['namespace']} bucket={real} key={p['key']!r}" if p else f"{uri}\n  -> unparseable")

